// Verwacht in het onderwerp: "<type> <werknr> <datum>"
// bijv. "ziek 12345 2026-09-15" of "beschikbaar 12345 2026-09-16"

const uit = [];

for (const item of $input.all()) {
  const ruw = String(item.json.subject || '').trim();
  const delen = ruw.split(/\s+/);

  const typeWoord = (delen[0] || '').toLowerCase();
  const werknr    = delen[1] || '';
  const datum     = delen[2] || '';

  let type = 'onbekend';
  if (typeWoord === 'ziek' || typeWoord === 'ziekmelding') type = 'ziekmelding';
  else if (typeWoord === 'beschikbaar') type = 'beschikbaar';

  const werknrOk = /^\d{4,6}$/.test(werknr);
    // Melder typt dd-mm-yyyy; we zetten dit om naar yyyy-mm-dd (ISO) voor intern gebruik.
  const datumMatch = datum.match(/^(\d{2})-(\d{2})-(\d{4})$/);
  let datumISO = '';
  let datumOk = false;
  if (datumMatch) {
    const [, dd, mm, jjjj] = datumMatch;
    const d = new Date(`${jjjj}-${mm}-${dd}`);
    // Check dat de datum ook echt bestaat (bijv. 31-02 valt af)
    datumOk =
      d instanceof Date &&
      !isNaN(d) &&
      d.getDate() === Number(dd) &&
      d.getMonth() + 1 === Number(mm);
    if (datumOk) datumISO = `${jjjj}-${mm}-${dd}`;
  }
  const geldig   = type !== 'onbekend' && werknrOk && datumOk;

  let validatieFout = '';
  if (type === 'onbekend')  validatieFout = 'type niet herkend';
  else if (!werknrOk)       validatieFout = 'werknemersnummer ontbreekt of klopt niet';
  else if (!datumOk)        validatieFout = 'datum ontbreekt of verkeerd formaat';

  // Afzender uitpakken (nodig om later de melder te antwoorden)
  const f = item.json.from;
  const afzender = typeof f === 'string'
    ? f
    : (f && f.value && f.value[0] && f.value[0].address) || (f && f.text) || '';

  uit.push({
    json: { type, werknr, datum, datumISO, geldig, validatieFout, afzender },
  });
}

return uit;

// KANDIDAAT KIEZEN — vereenvoudigde ATW-check (dag + weekgrens).
// De precieze rusttijd-berekening (11u tussen diensten) is een latere stap.

const MAX_WEEKUREN = 40;   // simulatiegrens, NIET de exacte wettelijke ATW-norm
const MIN_RUST_UREN = 11;  // ATW-hoofdregel: min. 11 aaneengesloten uren rust per 24u

const bron = $input.first().json;
const medewerkers = bron.medewerkers || [];
const rooster = bron.rooster || [];
const pool = bron.pool || [];

// Ziekmelding-context (pas de nodenaam aan als jouw roosternode anders heet):
const zm = $('Code in JavaScript1').first().json;
const datum = zm.datumISO;
const zieke = zm.werknr;

function urenTussen(start, eind) {
  const [sh, sm] = start.split(':').map(Number);
  const [eh, em] = eind.split(':').map(Number);
  return ((eh * 60 + em) - (sh * 60 + sm)) / 60;
}
const nieuweDienstUren = urenTussen(zm.dienstStart, zm.dienstEind);

// Maandag van de week waarin de datum valt
function weekStart(iso) {
  const d = new Date(iso + 'T00:00:00');
  const dag = (d.getDay() + 6) % 7; // ma=0 ... zo=6
  d.setDate(d.getDate() - dag);
  return d;
}
const wkStart = weekStart(datum);
const wkEind = new Date(wkStart); wkEind.setDate(wkEind.getDate() + 6);
function inWeek(iso) {
  const d = new Date(iso + 'T00:00:00');
  return d >= wkStart && d <= wkEind;
}

// Maakt een vergelijkbaar tijdstip van een datum (jjjj-mm-dd) + tijd (uu:mm)
function tijdstip(datumISO, tijd) {
  return new Date(`${datumISO}T${tijd}:00`);
}

// Uren tussen twee tijdstippen (mag over middernacht heen)
function urenVerschil(a, b) {
  return Math.abs(b - a) / (1000 * 60 * 60);
}

const kandidaten = [];
for (const m of medewerkers) {
  // beschikbaar = heeft zich gemeld voor precies deze datum
  const beschikbaar = pool.some(p =>
    String(p.werknemersnummer) === String(m.werknemersnummer) && p.datum === datum
  );
  if (!beschikbaar) continue;                  // alleen wie zich voor deze datum meldde
  if (String(m.werknemersnummer) === String(zieke)) continue;  // niet de zieke zelf

   const eigen = rooster.filter(r => String(r.werknemersnummer) === String(m.werknemersnummer));
  const werktDieDag = eigen.some(r => r.datum === datum);
  const weekUren = eigen.filter(r => inWeek(r.datum))
                        .reduce((som, r) => som + Number(r.uren), 0);

   // Rusttijd-check: botst de nieuwe dienst met de dienst van de dag ervoor of erna?
  const nieuweStart = tijdstip(datum, zm.dienstStart);
  const nieuweEind  = tijdstip(datum, zm.dienstEind);

  let genoegRust = true;
  for (const r of eigen) {
    const rStart = tijdstip(r.datum, r.start);
    const rEind  = tijdstip(r.datum, r.eind);

    // alleen aangrenzende diensten zijn relevant (binnen ~48u van de nieuwe dienst)
    const rustVoor = urenVerschil(rEind, nieuweStart);   // eigen dienst eindigt, nieuwe begint
    const rustNa   = urenVerschil(nieuweEind, rStart);   // nieuwe eindigt, eigen dienst begint

    if (rEind <= nieuweStart && rustVoor < MIN_RUST_UREN) genoegRust = false;
    if (rStart >= nieuweEind && rustNa   < MIN_RUST_UREN) genoegRust = false;
  }

  let afvalReden = '';
  if (werktDieDag) afvalReden = 'werkt die dag al';
  else if (weekUren + nieuweDienstUren > MAX_WEEKUREN) afvalReden = 'te veel uren deze week';
  else if (!genoegRust) afvalReden = 'te weinig rusttijd tussen diensten';

  kandidaten.push({
    werknemersnummer: m.werknemersnummer,
    naam: m.naam,
    email: m.email,
    contractsoort: m.contractsoort,
    weekUren,
    naDienst: weekUren + nieuweDienstUren,
    geschikt: afvalReden === '',
    afvalReden,
  });
}

// Geschikte kandidaten sorteren: flex eerst, dan minste weekuren (eerlijk verdelen)
const geschikt = kandidaten
  .filter(k => k.geschikt)
  .sort((a, b) => {
    const aFlex = a.contractsoort === 'flex' ? 0 : 1;
    const bFlex = b.contractsoort === 'flex' ? 0 : 1;
    if (aFlex !== bFlex) return aFlex - bFlex;
    return a.weekUren - b.weekUren;
  });

return [{
  json: {
    datum,
    teVervangenDienst: `${zm.dienstStart}-${zm.dienstEind}`,
    nieuweDienstUren,
    aantalGeschikt: geschikt.length,
    gekozenKandidaat: geschikt[0] || null,   // wie we als eerste vragen (of null)
    geschikteKandidaten: geschikt,           // volgorde waarin we zouden vragen
    afgevallen: kandidaten.filter(k => !k.geschikt), // met reden, handig om te tonen
  },
}];

// Bouwt de conceptaanvraag voor het uitzendbureau.
// BEWUST minimaal: geen namen, geen werknemersnummer van de zieke, geen reden.

const zm = $('Code in JavaScript1').first().json;

const aanvraag = {
  datum: zm.datumISO,
  dienstStart: zm.dienstStart,
  dienstEind: zm.dienstEind,
  aantalUren: (() => {
    const [sh, sm] = String(zm.dienstStart).split(':').map(Number);
    const [eh, em] = String(zm.dienstEind).split(':').map(Number);
    return ((eh * 60 + em) - (sh * 60 + sm)) / 60;
  })(),
  functie: 'medewerker bediening',
};

return [{ json: aanvraag }];

