// Zet het API-antwoord om naar de platte velden die de flow verwacht,
// en draagt de melding-context mee uit de parser.

const api = $json;                              // antwoord van de HTTP Request
const zm  = $('mail naar data').first().json;   // parser-output (werknr, datumISO, afzender, geldig)

const dienst = api.dienst || null;
const dienstGevonden = api.dienstGevonden === true;

let stopReden = '';
if (!zm.geldig)                 stopReden = zm.validatieFout || 'melding onvolledig';
else if (!api.nummerBekend)     stopReden = 'werknemersnummer onbekend in rooster';
else if (!dienstGevonden)       stopReden = 'geen dienst gepland op deze datum';

const magDoor = zm.geldig && dienstGevonden;

return [{
  json: {
    ...zm,
    nummerBekend: api.nummerBekend === true,
    dienstGevonden,
    dienstStart: dienst ? dienst.start : '',
    dienstEind:  dienst ? dienst.eind  : '',
    stopReden,
    magDoor,
  },
}];

